import "server-only";

import { getAIProvider } from "@/features/ai/providers";
import { AI_CONFIG } from "@/lib/constants";
import { prisma } from "@/lib/prisma";

import { executePipeline } from "../core/pipeline";
import type { IntelligenceReport } from "../core/pipeline";
import type { BriefSection } from "../core/types";
import { getConfidenceLevel } from "../trust/types";
import type { TrustEnvelope } from "../trust/types";

/**
 * CEO Brief v1 — Generated by Atlas Brain, NOT by directly prompting the LLM.
 *
 * Pipeline:
 * 1. Execute full brain pipeline (observe→prepare)
 * 2. Feed structured intelligence report into brief generator
 * 3. Wrap output in TrustEnvelope
 */

const BRIEF_GENERATION_PROMPT = `You are Atlas, a Management Intelligence Platform generating an executive brief.

You are given a structured intelligence report. Transform it into a concise, actionable brief.

Sections to produce (in this order):
1. "Company Pulse" — summarize health score, trend, and top contributors
2. "Top 3 Priorities" — the most important items requiring attention
3. "Executive Insights" — key patterns and observations
4. "Recommended Actions" — prepared actions awaiting approval
5. "Confidence Assessment" — what Atlas is confident about and what needs more data

For each section assign priority: "high", "medium", or "low".
Write in a direct, executive tone. No fluff. Lead with what matters.

Respond with ONLY a JSON array of {heading, content, priority}. No markdown fences.`;

export async function generateBrief(
  organizationId: string,
  type: "DAILY" | "WEEKLY"
): Promise<{
  id: string;
  sections: BriefSection[];
  trust: TrustEnvelope<IntelligenceReport>;
}> {
  // Step 1: Execute brain pipeline
  const intelligence = await executePipeline(organizationId);
  const report = intelligence.data;

  // Step 2: Generate brief sections
  let sections: BriefSection[];

  try {
    const provider = getAIProvider();
    const { content } = await provider.complete({
      model: AI_CONFIG.defaultModel,
      messages: [
        { role: "system", content: BRIEF_GENERATION_PROMPT },
        {
          role: "user",
          content: JSON.stringify({
            pulse: {
              score: report.pulse.score,
              trend: report.pulse.trend,
              dimensions: report.pulse.dimensions,
              topContributors: report.pulse.topContributors,
            },
            priorities: report.priorities,
            insights: report.insights,
            recommendedActions: report.recommendedActions,
            confidence: intelligence.confidence,
            confidenceLevel: getConfidenceLevel(intelligence.confidence),
            missingInformation: intelligence.missingInformation,
            dataPoints: report.dataPoints,
          }),
        },
      ],
      temperature: 0.4,
      maxTokens: 2000,
    });

    const parsed = JSON.parse(content.trim());
    sections = Array.isArray(parsed)
      ? parsed
      : buildFallbackSections(report, intelligence);
  } catch (_error) {
    sections = buildFallbackSections(report, intelligence);
  }

  // Step 3: Persist
  const now = new Date();
  const periodStart = new Date(now);
  if (type === "DAILY") {
    periodStart.setHours(0, 0, 0, 0);
  } else {
    periodStart.setDate(periodStart.getDate() - 7);
    periodStart.setHours(0, 0, 0, 0);
  }

  const title =
    type === "DAILY"
      ? `Daily Brief — ${now.toLocaleDateString("en-US", { month: "short", day: "numeric" })}`
      : `Weekly Brief — Week of ${periodStart.toLocaleDateString("en-US", { month: "short", day: "numeric" })}`;

  const brief = await prisma.brief.create({
    data: {
      organizationId,
      type,
      title,
      sections: JSON.parse(JSON.stringify(sections)),
      periodStart,
      periodEnd: now,
    },
  });

  return { id: brief.id, sections, trust: intelligence };
}

function buildFallbackSections(
  report: IntelligenceReport,
  trust: TrustEnvelope<IntelligenceReport>
): BriefSection[] {
  return [
    {
      heading: "Company Pulse",
      content: `Pulse score: ${report.pulse.score}/100 (${report.pulse.trend}). Based on ${report.dataPoints} data points.`,
      priority: "high",
    },
    {
      heading: "Top Priorities",
      content:
        report.priorities.length > 0
          ? report.priorities.map((p: { title: string }) => p.title).join(", ")
          : "No high-priority items detected.",
      priority: report.priorities.length > 0 ? "high" : "low",
    },
    {
      heading: "Confidence Assessment",
      content: `Confidence: ${Math.round(trust.confidence * 100)}%. Missing: ${trust.missingInformation.join("; ")}.`,
      priority: "medium",
    },
  ];
}

export async function getLatestBrief(
  organizationId: string,
  type: "DAILY" | "WEEKLY"
) {
  return prisma.brief.findFirst({
    where: { organizationId, type },
    orderBy: { createdAt: "desc" },
  });
}

export async function listBriefs(organizationId: string, limit: number = 14) {
  return prisma.brief.findMany({
    where: { organizationId },
    orderBy: { createdAt: "desc" },
    take: limit,
    select: {
      id: true,
      type: true,
      title: true,
      createdAt: true,
    },
  });
}
